// Smoke test: measured input → O-SSM → output conf ≤ 0.965 (asserted B dominates)

fn sqrt_t(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x; var i = 0
    while i < 10 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}
fn abs_t(x: f64) -> f64 { if x < 0.0 { 0.0 - x } else { x } }
fn exp_t(x: f64) -> f64 with Mut, Div, Panic {
    if x > 20.0 { return exp_t(10.0) * exp_t(x - 10.0) }
    if x < 0.0 - 20.0 { return 0.0 }
    var s = 1.0; var t = 1.0; var i = 1
    while i <= 15 { t = t * x / (i as f64); s = s + t; i = i + 1 }
    s
}
fn sig_t(x: f64) -> f64 with Mut, Div, Panic { 1.0 / (1.0 + exp_t(0.0 - x)) }

struct Oct { e: [f64; 8] }
fn oct_mul(a: &Oct, b: &Oct) -> Oct with Mut, Div, Panic {
    var o: [f64; 8] = [0.0; 8]
    o[0] = a.e[0]*b.e[0]-a.e[1]*b.e[1]-a.e[2]*b.e[2]-a.e[3]*b.e[3]-a.e[4]*b.e[4]-a.e[5]*b.e[5]-a.e[6]*b.e[6]-a.e[7]*b.e[7]
    o[1] = a.e[0]*b.e[1]+a.e[1]*b.e[0]+a.e[2]*b.e[3]-a.e[3]*b.e[2]+a.e[4]*b.e[5]-a.e[5]*b.e[4]-a.e[6]*b.e[7]+a.e[7]*b.e[6]
    o[2] = a.e[0]*b.e[2]+a.e[2]*b.e[0]-a.e[1]*b.e[3]+a.e[3]*b.e[1]+a.e[4]*b.e[6]-a.e[6]*b.e[4]+a.e[5]*b.e[7]-a.e[7]*b.e[5]
    o[3] = a.e[0]*b.e[3]+a.e[3]*b.e[0]+a.e[1]*b.e[2]-a.e[2]*b.e[1]+a.e[4]*b.e[7]-a.e[7]*b.e[4]-a.e[5]*b.e[6]+a.e[6]*b.e[5]
    o[4] = a.e[0]*b.e[4]+a.e[4]*b.e[0]-a.e[1]*b.e[5]+a.e[5]*b.e[1]-a.e[2]*b.e[6]+a.e[6]*b.e[2]-a.e[3]*b.e[7]+a.e[7]*b.e[3]
    o[5] = a.e[0]*b.e[5]+a.e[5]*b.e[0]+a.e[1]*b.e[4]-a.e[4]*b.e[1]-a.e[2]*b.e[7]+a.e[7]*b.e[2]+a.e[3]*b.e[6]-a.e[6]*b.e[3]
    o[6] = a.e[0]*b.e[6]+a.e[6]*b.e[0]+a.e[1]*b.e[7]-a.e[7]*b.e[1]+a.e[2]*b.e[4]-a.e[4]*b.e[2]-a.e[3]*b.e[5]+a.e[5]*b.e[3]
    o[7] = a.e[0]*b.e[7]+a.e[7]*b.e[0]-a.e[1]*b.e[6]+a.e[6]*b.e[1]-a.e[2]*b.e[5]+a.e[5]*b.e[2]+a.e[3]*b.e[4]-a.e[4]*b.e[3]
    Oct { e: o }
}

struct EK { val: f64, unc: f64, conf: f64 }
fn ek_measured(v: f64, u: f64) -> EK { EK { val: v, unc: u, conf: 0.985 } }

fn main() -> i32 with IO, Mut, Div, Panic {
    // One SSM step: h = sigmoid(A ⊗ 0 + B * x)
    let A = Oct { e: [0.2, 0.1, 0.3, 0.0 - 0.1, 0.0, 0.15, 0.0 - 0.2, 0.05] }
    let B = Oct { e: [0.3, 0.0 - 0.2, 0.1, 0.25, 0.0 - 0.1, 0.0, 0.2, 0.0 - 0.15] }
    let C = Oct { e: [0.25, 0.1, 0.0 - 0.1, 0.2, 0.05, 0.0 - 0.2, 0.15, 0.1] }
    let x  = ek_measured(0.5, 0.01)    // measured input

    // Bx = B * x.val; h = sigmoid(Bx)
    var bx: [f64; 8] = [0.0; 8]; var i = 0
    while i < 8 { bx[i as usize] = B.e[i as usize] * x.val; i = i + 1 }
    var h: [f64; 8] = [0.0; 8]; i = 0
    while i < 8 { h[i as usize] = sig_t(bx[i as usize]); i = i + 1 }
    let h_oct = Oct { e: h }

    // y = Re(C ⊗ h)
    let Ch = oct_mul(&C, &h_oct)
    let y_val = Ch.e[0]

    // B is asserted (conf=0.965), input is measured (conf=0.985)
    // output conf = min(B_conf, x_conf) = min(0.965, 0.985) = 0.965
    var out_conf = 0.965
    if x.conf < out_conf { out_conf = x.conf }

    if abs_t(y_val) > 0.0 && out_conf <= 0.965 + 0.001 {
        println("ossm_knowledge_basic: PASS")
        return 0
    }
    println("ossm_knowledge_basic: FAIL")
    return 1
}

//@ run-pass
//@ requires: madaros
//@ description: Tiny PB/Cardinality at-most-two bridge checker

fn pb_bool_valid(x: i64) -> i64 {
    if x == 0 { return 1 }
    if x == 1 { return 1 }
    if x == (0 - 1) { return 1 }
    return 0
}

fn pb_min_term(w: i64, x: i64) -> i64 {
    if x == 1 { return w }
    return 0
}

fn pb_min_sum3(w0: i64, x0: i64, w1: i64, x1: i64, w2: i64, x2: i64) -> i64 {
    return pb_min_term(w0, x0) + pb_min_term(w1, x1) + pb_min_term(w2, x2)
}

fn pb_check_le_contradiction3(w0: i64, x0: i64, w1: i64, x1: i64, w2: i64, x2: i64, rhs: i64) -> i64 {
    if w0 < 0 { return 0 }
    if w1 < 0 { return 0 }
    if w2 < 0 { return 0 }
    if pb_bool_valid(x0) == 0 { return 0 }
    if pb_bool_valid(x1) == 0 { return 0 }
    if pb_bool_valid(x2) == 0 { return 0 }
    if pb_min_sum3(w0, x0, w1, x1, w2, x2) > rhs { return 1 }
    return 0
}

fn pb_check_at_most_two_true_conflict3(x0: i64, x1: i64, x2: i64) -> i64 {
    return pb_check_le_contradiction3(1, x0, 1, x1, 1, x2, 2)
}

fn card_var(slot: i64) -> i64 {
    return slot + 1
}

fn card_valid_slot(n: i64, slot: i64) -> i64 {
    if slot < 0 { return 0 }
    if slot >= n { return 0 }
    return 1
}

fn card_at_most_two_clause_count(n: i64) -> i64 {
    if n < 3 { return 0 }
    return (n * (n - 1) * (n - 2)) / 6
}

fn card_at_most_two_clause_id(n: i64, a: i64, b: i64, c: i64) -> i64 {
    if card_valid_slot(n, a) == 0 { return 0 - 1 }
    if card_valid_slot(n, b) == 0 { return 0 - 1 }
    if card_valid_slot(n, c) == 0 { return 0 - 1 }
    if a == b { return 0 - 1 }
    if a == c { return 0 - 1 }
    if b == c { return 0 - 1 }

    var id: i64 = 1
    var i: i64 = 0
    while i < n {
        var j: i64 = i + 1
        while j < n {
            var k: i64 = j + 1
            while k < n {
                var hit: i64 = 0
                if i == a {
                    if j == b {
                        if k == c { hit = 1 }
                    }
                    if j == c {
                        if k == b { hit = 1 }
                    }
                }
                if i == b {
                    if j == a {
                        if k == c { hit = 1 }
                    }
                    if j == c {
                        if k == a { hit = 1 }
                    }
                }
                if i == c {
                    if j == a {
                        if k == b { hit = 1 }
                    }
                    if j == b {
                        if k == a { hit = 1 }
                    }
                }
                if hit == 1 { return id }
                id = id + 1
                k = k + 1
            }
            j = j + 1
        }
        i = i + 1
    }
    return 0 - 1
}

fn card_at_most_two_clause_len(n: i64, clause_id: i64) -> i64 {
    if clause_id < 1 { return 0 }
    if clause_id <= card_at_most_two_clause_count(n) { return 3 }
    return 0
}

fn card_at_most_two_lit(n: i64, clause_id: i64, pos: i64) -> i64 {
    if pos < 0 { return 0 }
    if pos >= 3 { return 0 }
    if card_at_most_two_clause_len(n, clause_id) != 3 { return 0 }

    var id: i64 = 1
    var i: i64 = 0
    while i < n {
        var j: i64 = i + 1
        while j < n {
            var k: i64 = j + 1
            while k < n {
                if id == clause_id {
                    if pos == 0 { return 0 - card_var(i) }
                    if pos == 1 { return 0 - card_var(j) }
                    return 0 - card_var(k)
                }
                id = id + 1
                k = k + 1
            }
            j = j + 1
        }
        i = i + 1
    }
    return 0
}

fn card_lit_matches_one3(clause_lit: i64, lit_a: i64, lit_b: i64, lit_c: i64) -> i64 {
    if clause_lit + lit_a == 0 { return 1 }
    if clause_lit + lit_b == 0 { return 1 }
    if clause_lit + lit_c == 0 { return 1 }
    return 0
}

fn card_verify_at_most_two_conflict(n: i64, clause_id: i64, lit_a: i64, lit_b: i64, lit_c: i64) -> i64 {
    if lit_a <= 0 { return 0 }
    if lit_b <= 0 { return 0 }
    if lit_c <= 0 { return 0 }
    if lit_a == lit_b { return 0 }
    if lit_a == lit_c { return 0 }
    if lit_b == lit_c { return 0 }

    let a = lit_a - 1
    let b = lit_b - 1
    let c = lit_c - 1
    if card_valid_slot(n, a) == 0 { return 0 }
    if card_valid_slot(n, b) == 0 { return 0 }
    if card_valid_slot(n, c) == 0 { return 0 }
    if card_at_most_two_clause_id(n, a, b, c) != clause_id { return 0 }

    let c0 = card_at_most_two_lit(n, clause_id, 0)
    let c1 = card_at_most_two_lit(n, clause_id, 1)
    let c2 = card_at_most_two_lit(n, clause_id, 2)
    if card_lit_matches_one3(c0, lit_a, lit_b, lit_c) == 0 { return 0 }
    if card_lit_matches_one3(c1, lit_a, lit_b, lit_c) == 0 { return 0 }
    if card_lit_matches_one3(c2, lit_a, lit_b, lit_c) == 0 { return 0 }
    return 1
}

fn pb_card_at_most_two_clause_matches3(clause_lit0: i64, clause_lit1: i64, clause_lit2: i64,
                                       lit_a: i64, lit_b: i64, lit_c: i64) -> i64 {
    if lit_a <= 0 { return 0 }
    if lit_b <= 0 { return 0 }
    if lit_c <= 0 { return 0 }
    if lit_a == lit_b { return 0 }
    if lit_a == lit_c { return 0 }
    if lit_b == lit_c { return 0 }
    if clause_lit0 >= 0 { return 0 }
    if clause_lit1 >= 0 { return 0 }
    if clause_lit2 >= 0 { return 0 }
    if clause_lit0 == clause_lit1 { return 0 }
    if clause_lit0 == clause_lit2 { return 0 }
    if clause_lit1 == clause_lit2 { return 0 }
    if card_lit_matches_one3(clause_lit0, lit_a, lit_b, lit_c) == 0 { return 0 }
    if card_lit_matches_one3(clause_lit1, lit_a, lit_b, lit_c) == 0 { return 0 }
    if card_lit_matches_one3(clause_lit2, lit_a, lit_b, lit_c) == 0 { return 0 }
    return 1
}

fn pb_check_card_at_most_two_clause_conflict3(clause_lit0: i64, clause_lit1: i64, clause_lit2: i64,
                                             lit_a: i64, lit_b: i64, lit_c: i64,
                                             x0: i64, x1: i64, x2: i64) -> i64 {
    if pb_card_at_most_two_clause_matches3(clause_lit0, clause_lit1, clause_lit2, lit_a, lit_b, lit_c) == 0 { return 0 }
    return pb_check_at_most_two_true_conflict3(x0, x1, x2)
}

fn bridge_at_most_two_conflict(n: i64, clause_id: i64, lit_a: i64, lit_b: i64, lit_c: i64,
                               x0: i64, x1: i64, x2: i64) -> i64 {
    if card_verify_at_most_two_conflict(n, clause_id, lit_a, lit_b, lit_c) == 0 { return 0 }
    let c0: i64 = card_at_most_two_lit(n, clause_id, 0)
    let c1: i64 = card_at_most_two_lit(n, clause_id, 1)
    let c2: i64 = card_at_most_two_lit(n, clause_id, 2)
    return pb_check_card_at_most_two_clause_conflict3(c0, c1, c2, lit_a, lit_b, lit_c, x0, x1, x2)
}

fn main() -> i64 {
    // In n=4, clause 4 is (-x2 OR -x3 OR -x4). PB view: x2+x3+x4 <= 2.
    if bridge_at_most_two_conflict(4, 4, 2, 3, 4, 1, 1, 1) != 1 { return 1 }
    if bridge_at_most_two_conflict(4, 4, 4, 2, 3, 1, 1, 1) != 1 { return 2 }
    if pb_card_at_most_two_clause_matches3(0 - 2, 0 - 3, 0 - 4, 2, 3, 4) != 1 { return 11 }
    if pb_check_card_at_most_two_clause_conflict3(0 - 2, 0 - 3, 0 - 4, 2, 3, 4, 1, 1, 1) != 1 { return 12 }

    // The cardinality clause alone is not enough: the PB contradiction requires
    // three true assignments, so two true plus unknown is not certified.
    if bridge_at_most_two_conflict(4, 4, 2, 3, 4, 1, 1, 0 - 1) != 0 { return 3 }
    if bridge_at_most_two_conflict(4, 4, 2, 3, 4, 1, 1, 0) != 0 { return 4 }
    if pb_check_card_at_most_two_clause_conflict3(0 - 2, 0 - 3, 0 - 4, 2, 3, 4, 1, 1, 0 - 1) != 0 { return 13 }

    // The PB row alone is not enough either: wrong IDs, repeated lits, signs, or
    // out-of-range variables must fail before the arithmetic certificate is used.
    if bridge_at_most_two_conflict(4, 3, 2, 3, 4, 1, 1, 1) != 0 { return 5 }
    if bridge_at_most_two_conflict(4, 4, 2, 2, 4, 1, 1, 1) != 0 { return 6 }
    if bridge_at_most_two_conflict(4, 4, 2, 3, 0 - 4, 1, 1, 1) != 0 { return 7 }
    if bridge_at_most_two_conflict(4, 4, 2, 3, 5, 1, 1, 1) != 0 { return 8 }
    if bridge_at_most_two_conflict(2, 1, 1, 2, 3, 1, 1, 1) != 0 { return 9 }
    if pb_card_at_most_two_clause_matches3(0 - 2, 0 - 2, 0 - 4, 2, 3, 4) != 0 { return 14 }
    if pb_card_at_most_two_clause_matches3(2, 0 - 3, 0 - 4, 2, 3, 4) != 0 { return 15 }
    if pb_card_at_most_two_clause_matches3(0 - 2, 0 - 3, 0 - 5, 2, 3, 4) != 0 { return 16 }
    if pb_card_at_most_two_clause_matches3(0 - 2, 0 - 3, 0 - 4, 2, 2, 4) != 0 { return 17 }

    // Bad PB assignments are rejected rather than certified.
    if bridge_at_most_two_conflict(4, 4, 2, 3, 4, 1, 2, 1) != 0 { return 10 }

    return 0
}

//@ run-pass
//@ description: Tiny pseudo-Boolean proof-checker smoke

fn pb_bool_valid(x: i64) -> i64 {
    if x == 0 { return 1 }
    if x == 1 { return 1 }
    if x == (0 - 1) { return 1 }
    return 0
}

fn pb_min_term(w: i64, x: i64) -> i64 {
    if x == 1 { return w }
    return 0
}

fn pb_max_term(w: i64, x: i64) -> i64 {
    if x == 0 { return 0 }
    return w
}

fn pb_min_sum3(w0: i64, x0: i64, w1: i64, x1: i64, w2: i64, x2: i64) -> i64 {
    return pb_min_term(w0, x0) + pb_min_term(w1, x1) + pb_min_term(w2, x2)
}

fn pb_max_sum3(w0: i64, x0: i64, w1: i64, x1: i64, w2: i64, x2: i64) -> i64 {
    return pb_max_term(w0, x0) + pb_max_term(w1, x1) + pb_max_term(w2, x2)
}

fn pb_check_le_contradiction3(w0: i64, x0: i64, w1: i64, x1: i64, w2: i64, x2: i64, rhs: i64) -> i64 {
    if w0 < 0 { return 0 }
    if w1 < 0 { return 0 }
    if w2 < 0 { return 0 }
    if pb_bool_valid(x0) == 0 { return 0 }
    if pb_bool_valid(x1) == 0 { return 0 }
    if pb_bool_valid(x2) == 0 { return 0 }
    if pb_min_sum3(w0, x0, w1, x1, w2, x2) > rhs { return 1 }
    return 0
}

fn pb_check_ge_contradiction3(w0: i64, x0: i64, w1: i64, x1: i64, w2: i64, x2: i64, rhs: i64) -> i64 {
    if w0 < 0 { return 0 }
    if w1 < 0 { return 0 }
    if w2 < 0 { return 0 }
    if pb_bool_valid(x0) == 0 { return 0 }
    if pb_bool_valid(x1) == 0 { return 0 }
    if pb_bool_valid(x2) == 0 { return 0 }
    if pb_max_sum3(w0, x0, w1, x1, w2, x2) < rhs { return 1 }
    return 0
}

fn pb_check_exactly_one_false_conflict3(x0: i64, x1: i64, x2: i64) -> i64 {
    return pb_check_ge_contradiction3(1, x0, 1, x1, 1, x2, 1)
}

fn pb_check_at_most_one_true_conflict3(x0: i64, x1: i64, x2: i64) -> i64 {
    return pb_check_le_contradiction3(1, x0, 1, x1, 1, x2, 1)
}

fn pb_saturate_coeff(w: i64, rhs: i64) -> i64 {
    if w < 0 { return 0 - 1 }
    if rhs < 0 { return 0 - 1 }
    if w > rhs { return rhs }
    return w
}

fn pb_check_saturation3(w0: i64, w1: i64, w2: i64, rhs: i64,
                        s0: i64, s1: i64, s2: i64) -> i64 {
    if rhs < 0 { return 0 }
    if w0 < 0 { return 0 }
    if w1 < 0 { return 0 }
    if w2 < 0 { return 0 }
    if s0 != pb_saturate_coeff(w0, rhs) { return 0 }
    if s1 != pb_saturate_coeff(w1, rhs) { return 0 }
    if s2 != pb_saturate_coeff(w2, rhs) { return 0 }
    return 1
}

fn pb_floor_div_nonneg(n: i64, divisor: i64) -> i64 with Div {
    if n < 0 { return 0 - 1 }
    if divisor <= 0 { return 0 - 1 }
    return n / divisor
}

fn pb_ceil_div_nonneg(n: i64, divisor: i64) -> i64 with Div {
    if n < 0 { return 0 - 1 }
    if divisor <= 0 { return 0 - 1 }
    return (n + divisor - 1) / divisor
}

fn pb_check_divide_le3(w0: i64, w1: i64, w2: i64, rhs: i64, divisor: i64,
                       q0: i64, q1: i64, q2: i64, qrhs: i64) -> i64 with Div {
    if divisor <= 0 { return 0 }
    if rhs < 0 { return 0 }
    if w0 < 0 { return 0 }
    if w1 < 0 { return 0 }
    if w2 < 0 { return 0 }
    if q0 != pb_floor_div_nonneg(w0, divisor) { return 0 }
    if q1 != pb_floor_div_nonneg(w1, divisor) { return 0 }
    if q2 != pb_floor_div_nonneg(w2, divisor) { return 0 }
    if qrhs != pb_floor_div_nonneg(rhs, divisor) { return 0 }
    return 1
}

fn pb_check_divide_ge3(w0: i64, w1: i64, w2: i64, rhs: i64, divisor: i64,
                       q0: i64, q1: i64, q2: i64, qrhs: i64) -> i64 with Div {
    if divisor <= 0 { return 0 }
    if rhs < 0 { return 0 }
    if w0 < 0 { return 0 }
    if w1 < 0 { return 0 }
    if w2 < 0 { return 0 }
    if q0 != pb_ceil_div_nonneg(w0, divisor) { return 0 }
    if q1 != pb_ceil_div_nonneg(w1, divisor) { return 0 }
    if q2 != pb_ceil_div_nonneg(w2, divisor) { return 0 }
    if qrhs != pb_ceil_div_nonneg(rhs, divisor) { return 0 }
    return 1
}

fn main() -> i64 with Div {
    if pb_min_sum3(2, 1, 3, 0 - 1, 5, 0) != 2 { return 1 }
    if pb_max_sum3(2, 1, 3, 0 - 1, 5, 0) != 5 { return 2 }

    // 2*x0 + 3*x1 + 5*x2 <= 4 is impossible once x0=x1=true.
    if pb_check_le_contradiction3(2, 1, 3, 1, 5, 0 - 1, 4) != 1 { return 3 }
    if pb_check_le_contradiction3(2, 1, 3, 0 - 1, 5, 0, 4) != 0 { return 4 }

    // 2*x0 + 3*x1 + 5*x2 >= 6 is impossible once x0=x1=x2=false.
    if pb_check_ge_contradiction3(2, 0, 3, 0, 5, 0, 6) != 1 { return 5 }
    if pb_check_ge_contradiction3(2, 0 - 1, 3, 0, 5, 0, 2) != 0 { return 6 }

    // Exactly-one contradiction: all three false violates sum >= 1.
    if pb_check_exactly_one_false_conflict3(0, 0, 0) != 1 { return 7 }
    if pb_check_exactly_one_false_conflict3(0, 0 - 1, 0) != 0 { return 8 }

    // At-most-one contradiction: two true literals force sum > 1.
    if pb_check_at_most_one_true_conflict3(1, 1, 0) != 1 { return 9 }
    if pb_check_at_most_one_true_conflict3(1, 0 - 1, 0) != 0 { return 10 }

    // Bad assignments and negative weights are rejected rather than certified.
    if pb_check_le_contradiction3(1, 2, 1, 1, 1, 1, 1) != 0 { return 11 }
    if pb_check_le_contradiction3(0 - 1, 1, 1, 1, 1, 1, 1) != 0 { return 12 }

    // Saturation proof step: 5*x0 + 2*x1 + 7*x2 <= 3 saturates to
    // 3*x0 + 2*x1 + 3*x2 <= 3 for Boolean variables.
    if pb_saturate_coeff(5, 3) != 3 { return 13 }
    if pb_saturate_coeff(2, 3) != 2 { return 14 }
    if pb_check_saturation3(5, 2, 7, 3, 3, 2, 3) != 1 { return 15 }
    if pb_check_saturation3(5, 2, 7, 3, 5, 2, 3) != 0 { return 16 }
    if pb_check_saturation3(5, 2, 7, 0 - 1, 0, 0, 0) != 0 { return 17 }

    // Use the saturated inequality as a checked arithmetic certificate.
    // Under x0=x1=true, even the saturated minimum is 5 > 3.
    if pb_check_le_contradiction3(3, 1, 2, 1, 3, 0 - 1, 3) != 1 { return 18 }

    // Division proof steps. A <= row divides with floor rounding:
    // 5*x0 + 2*x1 + 7*x2 <= 8  ==>  2*x0 + 1*x1 + 3*x2 <= 4.
    if pb_floor_div_nonneg(7, 2) != 3 { return 19 }
    if pb_check_divide_le3(5, 2, 7, 8, 2, 2, 1, 3, 4) != 1 { return 20 }
    if pb_check_divide_le3(5, 2, 7, 8, 2, 3, 1, 3, 4) != 0 { return 21 }

    // A >= row divides with ceil rounding:
    // 5*x0 + 2*x1 + 7*x2 >= 9  ==>  3*x0 + 1*x1 + 4*x2 >= 5.
    if pb_ceil_div_nonneg(7, 2) != 4 { return 22 }
    if pb_check_divide_ge3(5, 2, 7, 9, 2, 3, 1, 4, 5) != 1 { return 23 }
    if pb_check_divide_ge3(5, 2, 7, 9, 2, 2, 1, 4, 5) != 0 { return 24 }
    if pb_check_divide_ge3(5, 2, 7, 9, 0, 3, 1, 4, 5) != 0 { return 25 }
    if pb_check_divide_le3(0 - 1, 2, 7, 8, 2, 0, 1, 3, 4) != 0 { return 26 }

    return 0
}

//@ run-pass
// PBPK Validation: 2-compartment Euler model vs analytical Bateman equation
//
// Model: Dose → Gut (absorption) → Central (elimination)
//   dGut/dt     = -ka * Gut
//   dCentral/dt = ka * Gut - ke * Central
//
// Analytical (Bateman equation):
//   Gut(t)     = Dose * exp(-ka * t)
//   Central(t) = Dose * ka / (ka - ke) * (exp(-ke * t) - exp(-ka * t))
//   AUC(0→∞)   = Dose / ke  (for complete absorption)
//
// Parameters: Dose=500mg, ka=1.0/h, ke=0.1/h, dt=0.1h, 240 steps (24h)

struct PBPKState {
    t: f64,
    gut: f64,
    central: f64,
    auc: f64,
    cmax: f64,
    tmax: f64
}

fn euler_step(s: PBPKState, dt: f64) -> PBPKState with Mut {
    let ka = 1.0
    let ke = 0.1
    let d_gut = -ka * s.gut
    let d_central = ka * s.gut - ke * s.central
    let new_central = s.central + d_central * dt

    // Track Cmax/Tmax
    let new_t = s.t + dt
    var cmax = s.cmax
    var tmax = s.tmax
    if new_central > s.cmax {
        cmax = new_central
        tmax = new_t
    }

    PBPKState {
        t: new_t,
        gut: s.gut + d_gut * dt,
        central: new_central,
        auc: s.auc + s.central * dt,
        cmax: cmax,
        tmax: tmax
    }
}

fn main() -> i32 with IO, Div, Mut {
    var s = PBPKState {
        t: 0.0, gut: 500.0, central: 0.0,
        auc: 0.0, cmax: 0.0, tmax: 0.0
    }
    let dt = 0.1
    var i = 0

    while i < 240 {
        s = euler_step(s, dt)
        i = i + 1
    }

    // Print results for validation
    println(s.t)
    println(s.gut)
    println(s.central)
    println(s.auc)
    println(s.cmax)
    println(s.tmax)

    // Validate against analytical expectations:
    //
    // 1. Time should be 24.0h
    if s.t < 23.9 { return 1 }
    if s.t > 24.1 { return 2 }

    // 2. Gut should be ~0 (exp(-24) ≈ 1.9e-11)
    if s.gut > 0.01 { return 3 }

    // 3. Central: Bateman at t=24h
    //    C(24) = 500 * 1.0/(1.0-0.1) * (exp(-0.1*24) - exp(-1.0*24))
    //          = 555.56 * (exp(-2.4) - exp(-24))
    //          = 555.56 * (0.0907 - ~0)
    //          = ~50.4 mg
    //    Euler with dt=0.1 will be close but not exact
    if s.central < 30.0 { return 4 }
    if s.central > 70.0 { return 5 }

    // 4. AUC should be substantial (analytical AUC_0-inf = Dose/ke = 5000)
    //    But we only integrate to 24h, so expect ~4000-5000
    if s.auc < 3000.0 { return 6 }
    if s.auc > 6000.0 { return 7 }

    // 5. Cmax should be ~200-300 mg (depends on ka/ke ratio)
    //    Analytical Cmax at tmax = ln(ka/ke)/(ka-ke) = ln(10)/0.9 ≈ 2.56h
    //    Cmax = 500*(1.0/0.9)*(0.1^(0.1/0.9) - 0.1^(1.0/0.9))
    //    Euler approximation: should be in ballpark
    if s.cmax < 100.0 { return 8 }
    if s.cmax > 400.0 { return 9 }

    // 6. Tmax should be near 2.56h (analytical)
    if s.tmax < 1.5 { return 10 }
    if s.tmax > 4.0 { return 11 }

    return 0
}

